\[
\begin{aligned}
&\Big|N\times(\frac1{N_1^2}\sum_{i=1}^N\sum_{j\ne i}Z_iZ_j\hat e_i(d)\hat e_j(d)K(\frac{d_{ij}}{b_N})-\frac1{N^2p^2}\sum_{i=1}^N\sum_{j\ne i}Z_iZ_j\hat e_i(d)\hat e_j(d)K(\frac{d_{ij}}{b_N}))\Big|&&\text{(127)}\\
&\le\Big(\frac{N^2}{N_1^2}-\frac1{p^2}\Big)\Big|\frac1N\sum_{i=1}^N\sum_{j\ne i}Z_iZ_j\hat e_i(d)\hat e_j(d)K(\frac{d_{ij}}{b_N})\Big|&&\text{(128)}\\
&\lesssim\Big(\frac{N^2}{N_1^2}-\frac1{p^2}\Big)\big(b_N^2\times K_{max}\big)=O_p(N^{-\frac12}b_N^2)=o_p(1)&&\text{(129)}
